"""HTTP routes delegate every write to Store."""
from http.server import BaseHTTPRequestHandler, HTTPServer
import json
import re
from urllib.parse import urlsplit

from .store import Store


class Handler(BaseHTTPRequestHandler):
    def log_message(self, *args):
        pass

    def reply(self, status, payload):
        body = json.dumps(payload).encode()
        self.send_response(status)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def do_GET(self):
        path = urlsplit(self.path).path
        if path == "/health":
            self.reply(200, {"ok": True})
        elif path == "/todos":
            self.reply(200, self.server.store.list_all())
        else:
            self.reply(404, {"error": "route not found"})

    def do_POST(self):
        path = urlsplit(self.path).path
        try:
            if path == "/todos":
                length = int(self.headers.get("Content-Length", "0"))
                if not 0 < length <= 65536:
                    raise ValueError("body must be 1..65536 bytes")
                body = json.loads(self.rfile.read(length))
                self.reply(201, self.server.store.add(body.get("title")))
            elif match := re.fullmatch(r"/todos/([0-9]+)/done", path):
                self.reply(200, self.server.store.transition(int(match[1]), "done"))
            else:
                self.reply(404, {"error": "route not found"})
        except KeyError:
            self.reply(404, {"error": "todo not found"})
        except (ValueError, AttributeError) as error:
            self.reply(409, {"error": str(error)})

    def do_DELETE(self):
        path = urlsplit(self.path).path
        try:
            if match := re.fullmatch(r"/todos/([0-9]+)", path):
                self.reply(200, self.server.store.transition(int(match[1]), "archived"))
            else:
                self.reply(404, {"error": "route not found"})
        except KeyError:
            self.reply(404, {"error": "todo not found"})
        except ValueError as error:
            self.reply(409, {"error": str(error)})


def serve(port, data):
    server = HTTPServer(("127.0.0.1", port), Handler)
    server.store = Store(data)
    try:
        server.serve_forever()
    finally:
        server.server_close()

"""Own JSON persistence, cross-process locking, and status transitions."""
import fcntl
import json
import os
from pathlib import Path
import tempfile

TRANSITIONS = {"open": "done", "done": "archived"}


class Store:
    def __init__(self, data):
        self.data = Path(data)
        self.data.mkdir(parents=True, exist_ok=True)
        self.path = self.data / "todos.json"

    def _transaction(self, change=None):
        # A separate lock inode survives atomic replacement of the JSON file.
        with (self.data / "todos.lock").open("a+") as lock:
            fcntl.flock(lock, fcntl.LOCK_EX)
            rows = json.loads(self.path.read_text()) if self.path.exists() else []
            result = change(rows) if change else rows
            if change:
                fd, name = tempfile.mkstemp(prefix=".todos-", dir=self.data)
                try:
                    with os.fdopen(fd, "w") as out:
                        json.dump(rows, out, sort_keys=True)
                        out.flush()
                        os.fsync(out.fileno())
                    os.replace(name, self.path)
                finally:
                    if os.path.exists(name):
                        os.unlink(name)
            return result

    def list_all(self):
        return self._transaction()

    def add(self, title):
        if not isinstance(title, str) or not title.strip():
            raise ValueError("title must be a nonempty string")

        def change(rows):
            row = {"id": max((r["id"] for r in rows), default=0) + 1,
                   "title": title.strip(), "status": "open"}
            rows.append(row)
            return row
        return self._transaction(change)

    def transition(self, todo_id, target):
        def change(rows):
            row = next((r for r in rows if r["id"] == todo_id), None)
            if row is None:
                raise KeyError(todo_id)
            if TRANSITIONS.get(row["status"]) != target:
                raise ValueError(f"cannot move {row['status']} to {target}")
            row["status"] = target
            return row
        return self._transaction(change)

